class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        result = []

        for query in queries:
            if query[0] == 2:  # update query
                index, color = query[1], query[2]
                colors[index] = color
            else:  # count query
                size = query[1]
                count = 0

                # For size 1, every single tile is an alternating group
                if size == 1:
                    count = n
                else:
                    # Check each possible starting position in the circular array
                    for start in range(n):
                        # Check if we can form an alternating group of given size starting at 'start'
                        valid = True

                        # Check the alternating pattern within the group (adjacent pairs)
                        for i in range(size - 1):
                            current_pos = (start + i) % n
                            next_pos = (start + i + 1) % n
                            if colors[current_pos] == colors[next_pos]:
                                valid = False
                                break

                        if valid:
                            count += 1

                result.append(count)

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Calculate final position using the formula: row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Group picks by player
        player_picks = {}
        for player, color in pick:
            if player not in player_picks:
                player_picks[player] = []
            player_picks[player].append(color)

        # Count winning players
        winning_count = 0

        for player in range(n):
            if player not in player_picks:
                # Player has no picks, can't win
                continue

            # Count frequency of each color picked by this player
            color_count = {}
            for color in player_picks[player]:
                color_count[color] = color_count.get(color, 0) + 1

            # Check if player wins: need at least (player + 1) balls of same color
            # Player i needs at least (i+1) balls of same color
            max_count = max(color_count.values()) if color_count else 0

            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate minimum flips needed to make all rows palindromic
        rows_flips = 0
        for i in range(m):
            row_flips = 0
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1
            rows_flips += row_flips

        # Calculate minimum flips needed to make all columns palindromic
        cols_flips = 0
        for j in range(n):
            col_flips = 0
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1
            cols_flips += col_flips

        # Return the minimum of the two options
        return min(rows_flips, cols_flips)

